import {COMPONENT_ARTICLES,componentTopic} from './component-help.js?v=2.5.5';
import {STUDY_ARTICLES,studyTopic} from './study-help.js?v=2.5.5';
import {screenGuideHTML} from './screen-guides.js?v=2.5.5';
import {CALCULATION_ARTICLES,renderEquation,renderReferenceFigure,renderReferenceTable} from './calculation-reference.js?v=2.5.5';
// One source for the help panel, contextual guidance and printable manual.
const section=(heading,paragraphs=[],bullets=[])=>({heading,paragraphs,bullets});
export const HELP_ARTICLES=[
{id:'waveforms',title:'Prepare and import waveform files',tags:'csv txt json mat samples time units format',summary:'Import finite, time-ordered signals with explicit units and a useful steady-state window.',sections:[section('File preparation',['Import CSV or TXT files with named columns and consistent row widths, JSON files with a columns object or numeric matrix, or numeric matrices stored in MATLAB level-5 MAT files. MAT v7.3/HDF5 is not supported by this importer. All files in one batch must use the same signal names.','Choose a time column containing at least two finite, strictly increasing samples. Imported signal arrays must match its length and contain finite numeric values; malformed files are rejected.']),section('Units and window',['Set time and signal units deliberately: seconds, amperes and volts are the internal calculation units. A microsecond trace interpreted as seconds changes event rates and losses dramatically.','The last selected duration of each file is used. Boundary samples are interpolated. Choose settled, representative data and preferably an integer number of relevant cycles. Very short windows, startup transients or inadequate switching-edge sampling can give misleading event counts or spectra.'])]},
{id:'mapping',title:'Map component signals and converter power',tags:'current voltage gate phase neutral polarity efficiency power output',summary:'Choose the signals each model uses and preserve the intended power-flow direction.',sections:[section('Component mapping',['Map current and voltage for every component bank. MOSFETs also need a gate signal. The mapped current represents the whole bank; series/parallel settings determine per-device conditions. Check that these variables exist in every imported file.','Waveform signs are retained in the debugger. Some characteristic queries intentionally use current or voltage magnitudes. Reverse gate-on MOSFET current uses the symmetric channel model; gate-off reverse current uses the body path when enabled.']),section('Power mapping',['Delivered output power is the time average of signed voltage × current, summed across mapped pairs. Efficiency is Pout / (Pout + included losses). Output power must be positive for a valid efficiency result; check pair polarity for the intended direction of energy flow.','For AC, pair phase-to-neutral voltage with that phase current. Balanced ×3 uses exactly one phase pair; do not map three phases and also multiply by three. Input waveform power is a separate balance check; discrepancies are not allocated to invented loss categories.'])]},
{id:'components',title:'Components alternatives and enabled losses',tags:'mosfet diode capacitor inductor exclude alternative candidate',summary:'Configure each physical component bank separately and enable only the contributions you model.',sections:[section('Instances and alternatives',['An instance is a named bank such as Q1, Q2, C1 or L1. Alternatives are candidate parts for that instance. A combination selects one alternative from every instance. All alternatives share the imported waveforms.','Alternatives of one instance must use the same enabled loss categories for a consistent comparison.']),section('Applicable contributions',[],['MOSFET: channel conduction, body diode conduction, turn-on, turn-off and reverse recovery.','Diode: forward conduction and reverse recovery.','Capacitor: ESR loss.','Inductor: winding/copper and core loss.']),section('Excluded versus zero',['Excluded means you deliberately disabled a contribution. An enabled contribution returning 0 W is a calculated result. Missing required characteristics cause an incomplete result; they are never silently treated as zero.'])]},
{id:'counts',title:'Series parallel and total device counts',tags:'count devices bank sharing current voltage replication',summary:'Counts scale per-device electrical conditions and total bank loss.',sections:[section('Series and parallel',['With ideal sharing, parallel devices each carry the mapped bank current divided by the parallel count; series devices each block the mapped voltage divided by the series count. Total bank loss sums the physical device losses.','Example: 20 A through two parallel devices gives 10 A per device. A constant 20 mΩ resistance gives 2 W per device and 4 W for that parallel bank. Two devices in series across 800 V each see 400 V in this model.']),section('Total count and limitations',['Use positive integers. Normally total physical count equals series × parallel. A different total requires confirmation for additional replicated banks. Do not increase total count simply to fix an input warning.','Ideal sharing does not account for layout, tolerance, temperature imbalance or dynamic voltage/current sharing. Validate these separately.'])]},
{id:'interpolation',title:'Interpolation and out-of-domain policies',tags:'forward reference family invert temperature vgs rg extrapolate clamp legacy',summary:'Choose the order of curve/dependency interpolation and how queries outside coverage are handled.',sections:[section('Interpolation methods',['Forward family first, then invert is the default for new studies: form the forward characteristic at requested dependencies, then invert it if the query direction requires this. Nonmonotonic or flat combined inverse branches are rejected.','Reference-curve interpolation queries each reference curve first, then interpolates the results across dependencies. Previously saved studies retain their method; pre-method projects retain reference-first behaviour. Weighted inverse-distance averaging is a separate heuristic, not rectangular linear interpolation.']),section('Domain policies',['Error rejects queries outside supported reference ranges. Clamp uses boundary conditions. Linear extrapolation extends the boundary segment or supported dependency model. Legacy compatibility retains older duplicate and inverse-axis rules; it is not a physical validation guarantee.','Example: extending points (10 A, 0.2 V) and (20 A, 0.5 V) gives −0.07 V at 1 A. The algebra is linear, but the negative drop magnitude is invalid for this loss model. Edit the data or review an explicit zero floor.']),section('Sparse data',['Complete reference grids use rectangular interpolation. Sparse families can use a simplex between reference conditions; unsupported coverage may fail. Extrapolation adds model uncertainty even when the chosen policy allows it.'])]},
{id:'gates',title:'Logic and analog gate signals',tags:'threshold on off hysteresis vgs gate rg switching',summary:'Gate type determines state detection and the voltage used for characteristic queries.',sections:[section('Logic signals',['Logic mode treats gate >0.5 as ON and gate ≤0.5 as OFF. Enter the actual gate-drive ON and OFF voltages separately; these supply Vgs reference conditions. Analog threshold fields are hidden because they are not used in this mode.']),section('Analog signals',['Analog mode uses the mapped gate voltage directly. State turns ON at or above the ON threshold and OFF at or below the OFF threshold. Between them the previous state is retained.','For thresholds 2 V / 0 V, a sequence 0, 1, 2, 1, 0 V gives OFF, OFF, ON, ON, OFF. These are waveform-classification thresholds, not a fitted transistor threshold-voltage model. Review the event trace to check the selected values.']),section('Gate resistance',['Rg turn-on and Rg turn-off are the conditions used to query the corresponding energy curves. Use finite, nonnegative values and consistent datasheet definitions.'])]},
{id:'switching',title:'Conduction switching and recovery models',tags:'eon eoff qrr err body diode events integral loss',summary:'Understand which losses come from time integration and which come from event energy.',sections:[section('Conduction',['Channel or forward voltage is queried from a compatible current-driven curve, or resistance gives I²R. The engine integrates instantaneous conduction power over the applicable gate states. Device currents and total counts follow the bank settings.','Gate-on reverse MOSFET current uses a symmetric channel magnitude approximation. Gate-off reverse conduction needs its separate characteristic and enabled category.']),section('Switching and recovery',['Turn-on/off energies are queried at detected gate events, summed and divided by the window duration. When selected, linear blocking-voltage scaling uses a positive reference voltage. Event energies do not define switching-pulse shape or duration.','Recovery is inferred from forward current ending with blocking voltage. Err is an energy characteristic; Qrr × voltage is a charge-based approximation. Confirm the definition to avoid double counting recovery already included in Eon. Inspect event source current/voltage samples, which may occur at different times.'])]},
{id:'passives',title:'Capacitor ESR, inductor winding and core loss',tags:'fft spectrum harmonic dc resistance esr copper core flux turns area volume',summary:'Use the appropriate resistive and magnetic model for the waveform and data.',sections:[section('Resistance models',['Constant resistance uses total time-weighted RMS current: P = Irms²R. This includes any mean-current term. Frequency-dependent resistance uses harmonic RMS currents and the resistance at each frequency.','An inductor requires DC winding resistance when mean current is present. A capacitor’s frequency model supports an explicit DC series resistance for a real mean-current contribution; this is not insulation/leakage resistance. DC voltage alone does not imply DC capacitor current.']),section('Core model',['Core loss uses winding voltage integration to estimate flux swing; turns, effective core area and volume must be positive. Volt-second balance and a usable excitation frequency are required.',''])]},
{id:'thermal',title:'Fixed temperature and iterative thermal models',tags:'tj rth junction ambient convergence heatsink iteration',summary:'Temperature dependence can be fixed or solved with a scalar steady-state model.',sections:[section('Model setup',['Fixed mode evaluates losses at the entered temperature. Iterative mode uses the entered reference temperature and thermal resistance to seek a steady-state device temperature. Declare whether Rth applies per device or to the entire bank.','Do not apply both absolute temperature-dependent resistance and a separate normalised temperature multiplier to the same loss.']),section('Convergence and limits',['The solver uses damping and checks finite values, its configured temperature limit, a maximum of 80 iterations and a 0.05 °C residual criterion. Failure does not make a physically valid zero-loss result.','Use Model details → Thermal convergence to inspect trial temperatures, equilibrium targets, residuals and limits, including failed runs. Shared heatsink coupling and transient thermal impedance are not represented.'])]},
{id:'results',title:'Results component filters and alternative comparisons',tags:'ranking scope whole range point components percentages quota efficiency heatmap',summary:'Separate selected-component losses from whole-converter efficiency.',sections:[section('Comparison scope',['Use independent component and combination filters to show all banks, one bank such as Q1, or several such as Q1 + Q2. Loss subtotals and percentage shares use only selected banks. Converter efficiency continues to use all enabled component losses. Filters update existing results without rerunning.','Whole range has independent Vin, Vout and Pout filters. Fixed-voltage groups keep comparisons coherent.']),section('Combined breakdown',['Within each alternative’s bar, coloured contribution segments belong to the component block immediately below them. Hover or keyboard focus shows watts and share. Select either row to inspect that bank. Zero is a computed included contribution; Excluded is a disabled one.','The point explorer has separate Vin/Vout/Pout choices. Model details, warnings and debug follow the selected point and inspected alternative. Converter power flow is explicitly a whole-converter view even while component subtotals are filtered.']),section('Maps and exports',['Heatmaps group numerically equivalent coordinates. Continuous mode interpolates only supported regions and retains sample markers; unsupported gaps do not become data. CSV/JSON exports retain the complete result set; the report dialog has its own combination, point and section choices.'])]},
{id:'debug',title:'Debug characteristic queries and waveforms',tags:'inspection cursor failed graph raw interpolation event temperature',summary:'Trace a result back to the values and characteristics used by the engine.',sections:[section('Inspect a query',['Open Results → Explore an operating point → Debug & interpolation. Choose the bank, characteristic and query/event. Reference curves, the evaluated family and the selected query explain the interpolation.','Read the requested input, dependencies, returned value and raw projection. A zero-floor choice keeps both the negative raw value and the corrected value. An out-of-coverage marker deserves review even when extrapolation was allowed.']),section('When calculation fails',['Available failed-device queries, waveforms and thermal history remain inspectable. A setup failure may occur before any query exists, and constant models may have no characteristic-query graph. Use Check inputs and the component setup for those cases.'])]},
{id:'troubleshooting',title:'Troubleshooting and result completeness',tags:'error warning missing failure duplicate negative no results fix',summary:'Understand whether an issue blocks the study, one device or only efficiency.',sections:[section('Find the right place to fix',[],['Missing or inconsistent time/signal data: return to waveform import and units.','Unmapped bank signal: open the component mapping and check every file.','Missing characteristic or conflicting duplicate inputs: open the highlighted characteristic and its iteration/rows.','Out-of-coverage query: inspect reference data, dependencies and the selected domain policy.','Negative physical projection: edit the characteristic or explicitly review a zero floor; it may underestimate loss.','Thermal failure: inspect losses, temperature dependence, Rth scope, convergence and limits.']),section('Result states',['Complete results include all required enabled losses. Complete with assumptions requires review of accepted model/reference choices. Incomplete means at least part failed; Failed means no complete device result is available for that row.','One alternative can fail while others remain valid. To enter the overall ranking a combination needs valid results at every required point. Missing values are unavailable, not zero. Setup checks cannot predict every waveform query or final thermal condition.'])]},
{id:'saving',title:'Save projects reports and calculation records',tags:'download project json csv report print pdf autosave storage',summary:'Keep a portable project and choose export scopes deliberately.',sections:[section('Project and calculation records',['Save project downloads JSON with configuration, characteristic data and imported waveforms. Browser autosave is local and may exceed storage limits for large projects; check the save indicator and keep a downloaded copy.','Opening a project replaces the current study only after a successful import. Calculated results must be rerun. Full results JSON keeps detailed numerical/diagnostic records; summary and device CSV provide tabular exports.']),section('Reports and documentation',['The engineering report dialog lets you choose combinations, operating points and sections. Display filters do not silently change these export choices. Review report scope before downloading HTML or printing to PDF.','The Help Centre and printable manual share one content source. Open Full manual and use the browser Print / Save as PDF action for an offline copy.'])]},
];
HELP_ARTICLES.push(...STUDY_ARTICLES,...COMPONENT_ARTICLES,...CALCULATION_ARTICLES);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function articleHTML(article,options={}){const quick=options.quick===true;if(!article)return '<p>Article not found.</p>';return `<article class="help-article" id="manual-${esc(article.id)}"><h2>${esc(article.title)}</h2><p>${esc(article.summary)}</p>${quick?'':screenGuideHTML(article.id)}${!quick&&['components','switching','passives','interpolation','thermal'].includes(article.id)?`<nav class="doc-related" aria-label="Detailed calculation guides">${CALCULATION_ARTICLES.map(a=>`<a href="#manual-${a.id}" data-help-topic="${a.id}">${esc(a.title)} →</a>`).join('')}</nav>`:''}${article.sections.map(s=>`<h3>${esc(s.heading)}</h3>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${s.bullets.length?`<ul>${s.bullets.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}${(s.equations||[]).map(renderEquation).join('')}${(s.tables||[]).map(renderReferenceTable).join('')}${quick?'':(s.figures||[]).map(renderReferenceFigure).join('')}`).join('')}</article>`;}
export function searchHelp(query=''){const tokens=query.toLowerCase().trim().split(/\s+/).filter(Boolean);return HELP_ARTICLES.map(a=>{const title=(a.title+' '+a.tags).toLowerCase(),body=JSON.stringify(a.sections).toLowerCase();return {article:a,score:tokens.reduce((s,t)=>s+(title.includes(t)?3:body.includes(t)?1:0),0),match:tokens.every(t=>title.includes(t)||body.includes(t))};}).filter(r=>r.match).sort((a,b)=>b.score-a.score).map(r=>r.article);}
export function topicForField(path=''){const study=studyTopic(path)||componentTopic(path);if(study)return study;if(/mapping|Pairs|balanced|Polarity/.test(path))return 'mapping';if(/series|parallel|totalCount|replication/.test(path))return 'counts';if(/thermal/.test(path))return 'thermal';if(/recovery/.test(path))return 'switching';if(/origin|negativeOutput/.test(path))return 'interpolation';if(/gate|vgs|rgOn|rgOff/.test(path))return 'gates';if(/interpolation|domainPolicy/.test(path))return 'interpolation';if(/fftSize|Resistance|core|Vcore|Ae|N$|B0/.test(path))return 'passives';if(/window|time/.test(path))return 'waveforms';return 'components';}
export function topicForIssue(issue={}){const field=issue.field||'',specific=studyTopic(field)||componentTopic(field);if(specific)return specific;if(/negative (?:physical )?(?:magnitude|projection)|projected.*negative/i.test(issue.message||''))return 'interpolation';if(issue.curveId)return 'components';const topic=topicForField(field);return topic==='components'?(/Waveform/.test(issue.category||'')?'waveforms':'troubleshooting'):topic;}
export function setupSteps(project,checks,results){const issues=checks?.errors||[],hasW=!!project.waveforms?.length,hasI=!!project.instances?.length,blocked=pattern=>issues.some(i=>pattern.test(i.category||''));return [{id:'waveforms',title:'Import waveform files',page:'waveforms',topic:'waveforms',ready:hasW&&!blocked(/Waveform/)},{id:'mapping',title:'Map signals and power',page:'devices',topic:'mapping',ready:hasW&&hasI&&!blocked(/Signal mapping|Output power/)},{id:'components',title:'Configure components',page:'devices',topic:'components',ready:hasI&&!blocked(/Components|Comparison|Device settings|Gate settings|Thermal settings/)},{id:'characteristics',title:'Add active characteristics',page:'devices',topic:'components',ready:hasI&&!blocked(/Characteristics|Temperature correction|Recovery model|Core model/)},{id:'checks',title:'Check inputs and references',page:'checks',topic:'troubleshooting',ready:hasW&&hasI&&!issues.length},{id:'results',title:'Analyse and inspect results',page:'results',topic:'results',ready:!!results&&!results.screeningOnly&&results.rows?.length>0&&results.rows.every(r=>r.valid)}];}
export function fieldHelp(path,label){return `<button type="button" class="help-question" data-help-topic="${topicForField(path)}" data-help-field="${esc(path)}" aria-label="Help: ${esc(label)}" title="Help: ${esc(label)}">?</button>`;}
export function helpSearchHTML(query=''){const articles=searchHelp(query);return articles.length?articles.map(a=>`<button type="button" class="help-search-result" data-help-topic="${a.id}"><strong>${esc(a.title)}</strong><span>${esc(a.summary)}</span></button>`).join(''):'<p role="status">No matching article. Try a setting name such as ESR, thermal, gate or interpolation.</p>';}
export function helpRecapHTML(query=''){const matches=new Set(searchHelp(query).map(a=>a.id));const groups=[['Study settings and power mapping',STUDY_ARTICLES],['Component settings, gates and thermal',COMPONENT_ARTICLES],['Workflow and loss models',HELP_ARTICLES.filter(a=>!STUDY_ARTICLES.includes(a)&&!COMPONENT_ARTICLES.includes(a)&&!CALCULATION_ARTICLES.includes(a))]];return `<section class="help-recap"><h2>Quick-helper reference</h2><p>The same explanations shown beside each setting, collected here. Expand a topic to read its guidance.</p>${groups.map(([title,articles])=>{const shown=articles.filter(a=>matches.has(a.id));return shown.length?`<section><h3>${esc(title)}</h3>${shown.map(a=>`<details class="help-recap-topic"><summary>${esc(a.title)}</summary>${articleHTML(a,{quick:true})}</details>`).join('')}</section>`:'';}).join('')}${groups.every(([,articles])=>!articles.some(a=>matches.has(a.id)))?'<p role="status">No matching quick helper. Try a setting name such as gate, temperature or interpolation.</p>':''}</section>`;}
export function helpPanelHTML(state,project,checks,results){if(!state.open)return '';const selected=HELP_ARTICLES.find(a=>a.id===state.topic)||HELP_ARTICLES[0],steps=setupSteps(project,checks,results),issues=(checks?.issues||[]).slice(0,8);return `<aside class="help-centre" role="dialog" aria-modal="false" aria-labelledby="helpCentreTitle"><div class="help-header"><h2 id="helpCentreTitle">Help Centre</h2><button type="button" class="ghost" id="helpClose" aria-label="Close Help Centre">Close ×</button></div><label>Search documentation<input type="search" id="helpSearch" value="${esc(state.query||'')}" placeholder="Search settings, models or errors"></label><div class="toolbar"><button type="button" class="ghost" data-help-view="assistant">Setup assistant</button><button type="button" class="ghost" data-help-view="manual">Documentation</button><a class="ghost" href="manual.html" target="_blank" rel="noopener">Full manual ↗</a></div>${state.view==='assistant'?`<div class="help-steps">${steps.map(s=>`<div><span>${s.ready?'✓ Ready':'○ To check'}</span><button type="button" class="ghost" data-help-navigate="${s.page}">${esc(s.title)} →</button><button type="button" class="help-question" data-help-topic="${s.topic}" aria-label="Help: ${esc(s.title)}">?</button></div>`).join('')}</div><p class="caption">Setup readiness is not a guarantee of curve coverage or thermal convergence. Review notes before running.</p><h3>Guidance for this study</h3>${issues.length?issues.map(i=>`<section class="help-issue"><strong>${esc(i.device||i.category)}${i.part?' / '+esc(i.part):''}</strong><p>${esc(i.message)}</p><button type="button" class="ghost" data-help-fix="${esc(i.id)}">Open & fix →</button><button type="button" class="ghost" data-help-topic="${topicForIssue(i)}" data-help-quick="true">Why and how to fix</button></section>`).join(''):'<p>No setup issues are recorded. Run analysis, then inspect completeness, assumptions and debug coverage.</p>'}`:`<div id="helpSearchResults">${state.query&&!state.recap?helpSearchHTML(state.query):''}</div><div id="helpArticle">${state.recap?helpRecapHTML(state.query):articleHTML(selected,{quick:true})}</div><details><summary>All documentation topics</summary>${helpSearchHTML('')}</details>`}</aside>`;}
